package alphametics

import (
	"strings"
	"testing"
)

// bruteForce reports whether any valid assignment exists and validates a
// returned assignment for the given puzzle.
func brute(puzzle string) (bool, func(map[string]int) bool) {
	parts := strings.Split(puzzle, "==")
	lhs, rhs := strings.Split(parts[0], "+"), strings.TrimSpace(parts[1])
	words := []string{}
	for _, w := range lhs {
		words = append(words, strings.TrimSpace(w))
	}
	words = append(words, rhs)
	lead := map[byte]bool{}
	letters := []byte{}
	seen := map[byte]bool{}
	for _, w := range words {
		if len(w) > 1 {
			lead[w[0]] = true
		}
		for i := 0; i < len(w); i++ {
			if !seen[w[i]] {
				seen[w[i]] = true
				letters = append(letters, w[i])
			}
		}
	}
	val := func(m map[string]int, w string) int {
		n := 0
		for i := 0; i < len(w); i++ {
			n = n*10 + m[string(w[i])]
		}
		return n
	}
	ok := func(m map[string]int) bool {
		if len(m) != len(letters) {
			return false
		}
		used := map[int]bool{}
		for _, c := range letters {
			d, present := m[string(c)]
			if !present || used[d] {
				return false
			}
			if d == 0 && lead[c] {
				return false
			}
			used[d] = true
		}
		sum := 0
		for _, w := range words[:len(words)-1] {
			sum += val(m, w)
		}
		return sum == val(m, words[len(words)-1])
	}
	assign := map[string]int{}
	usedDigits := [10]bool{}
	var dfs func(i int) bool
	dfs = func(i int) bool {
		if i == len(letters) {
			return ok(assign)
		}
		c := letters[i]
		for d := 0; d <= 9; d++ {
			if usedDigits[d] || (d == 0 && lead[c]) {
				continue
			}
			usedDigits[d] = true
			assign[string(c)] = d
			if dfs(i + 1) {
				return true
			}
			delete(assign, string(c))
			usedDigits[d] = false
		}
		return false
	}
	return dfs(0), ok
}

func TestExtraSemantics(t *testing.T) {
	puzzles := []string{
		"A == A", "A == B", "A + B == C", "I + BB == ILL",
		"AB + A == C", "ACA + DD == BD", "AS + A == MOM",
		"NO + NO + TOO == LATE", "SEND + MORE == MONEY",
	}
	for _, p := range puzzles {
		want, valid := brute(p)
		got, err := Solve(p)
		if want != (err == nil) {
			t.Fatalf("Solve(%q) err=%v, brute-force satisfiable=%v", p, err, want)
		}
		if err == nil && !valid(got) {
			t.Fatalf("Solve(%q) returned invalid assignment %v", p, got)
		}
	}
	// A == A is trivially satisfiable with a single letter.
	if m, err := Solve("A == A"); err != nil || len(m) != 1 {
		t.Fatalf("A == A: %v %v", m, err)
	}
	// Eleven distinct letters can never be assigned.
	if _, err := Solve("ABCDEFGHIJ + A == A"); err == nil {
		t.Fatal("expected error for >10 letters")
	}
	// Whitespace tolerance.
	if m, err := Solve("  SEND +  MORE == MONEY "); err != nil || m["S"] != 9 || m["Y"] != 2 {
		t.Fatalf("whitespace case: %v %v", m, err)
	}
}
EOF
