import "testing"

func checkValid(t *testing.T, p string) map[string]int {
	t.Helper()
	m, err := Solve(p)
	if err != nil {
		t.Fatalf("Solve(%q) unexpected error: %v", p, err)
	}
	return m
}

func TestExtra(t *testing.T) {
	// no solution: A == A forces same letter to two digits
	if _, err := Solve("A == A"); err == nil {
		t.Fatal("A == A should be unsolvable")
	}
	// no solution: too many letters
	if _, err := Solve("ABCDEFGHIJ + A == A"); err == nil {
		t.Fatal("11 letters should error")
	}
	// leading zero invalid for multi-digit addend
	if _, err := Solve("AB + A == C"); err == nil {
		t.Fatal("expected error")
	}
	// single letters may be zero
	m := checkValid(t, "A + B == C")
	if m["A"]+m["B"] != m["C"] {
		t.Fatalf("bad A+B==C: %v", m)
	}
	// unicode/whitespace tolerance
	m = checkValid(t, "  SEND +  MORE == MONEY ")
	if m["S"] != 9 || m["Y"] != 2 {
		t.Fatalf("bad send more money: %v", m)
	}
	// result longer than max addend by more than one is impossible
	if _, err := Solve("A + B == CDEF"); err == nil {
		t.Fatal("expected error for too-long result")
	}
	// many addends, big carry
	m = checkValid(t, "A + A + A + A + A + A + A + A + A + A + A + B == BCC")
	if m["A"] != 9 || m["B"] != 1 || m["C"] != 0 {
		t.Fatalf("bad carry case: %v", m)
	}
	// verify a solved puzzle mathematically and uniqueness
	words := []string{"HE", "SEES", "THE"}
	m = checkValid(t, "HE + SEES + THE == LIGHT")
	seen := map[int]bool{}
	for _, d := range m { if seen[d] { t.Fatalf("dup digit %v", m) }; seen[d] = true }
	if len(m) != 7 { t.Fatalf("bad map %v", m) }
	_ = words
}
